// open-and-navigate.spec.ts - "Can I open a PDF and move between pages?"
// Uses the 2-page sample PDF in tests/fixtures/ (generated by
// `npm run generate-fixture`). Two pages are needed so "next page" has
// somewhere to go.
import { test, expect } from '@playwright/test';
import { PdfEditorPage } from '../pages/PdfEditorPage';

const SAMPLE_PDF = 'tests/fixtures/sample-2-pages.pdf';

test('opening a PDF shows its name, page 1 of 2, and the rendered page', async ({ page }) => {
  const editor = new PdfEditorPage(page);
  await editor.goto();
  await editor.openPdf(SAMPLE_PDF);

  await expect(editor.docName).toHaveText('sample-2-pages.pdf');
  await expect(editor.docMeta).toContainText('2 pages');
  await expect(editor.pageIndicator).toHaveText('1 / 2');
  await expect(editor.pdfCanvas).toBeVisible();
  // The empty state must disappear once a document is open.
  await expect(editor.emptyHeading).toBeHidden();
});

test('Next goes to page 2, Previous comes back to page 1', async ({ page }) => {
  const editor = new PdfEditorPage(page);
  await editor.goto();
  await editor.openPdf(SAMPLE_PDF);

  await editor.nextButton.click();
  await expect(editor.pageIndicator).toHaveText('2 / 2');

  await editor.prevButton.click();
  await expect(editor.pageIndicator).toHaveText('1 / 2');
});

test('Previous is disabled on page 1 and Next is disabled on the last page', async ({ page }) => {
  const editor = new PdfEditorPage(page);
  await editor.goto();
  await editor.openPdf(SAMPLE_PDF);

  await expect(editor.prevButton).toBeDisabled();
  await expect(editor.nextButton).toBeEnabled();

  await editor.nextButton.click();
  await expect(editor.pageIndicator).toHaveText('2 / 2');
  await expect(editor.nextButton).toBeDisabled();
  await expect(editor.prevButton).toBeEnabled();
});
test('going Next, Previous, Next again ends on page 2', async ({ page }) => {
  const editor = new PdfEditorPage(page);
  await editor.goto();
  await editor.openPdf(SAMPLE_PDF);


  await editor.nextButton.click();
  await expect(editor.pageIndicator).toHaveText('2 / 2');
  await editor.prevButton.click();
  await expect(editor.pageIndicator).toHaveText('1 / 2');
  await editor.nextButton.click();
  await expect(editor.pageIndicator).toHaveText('2 / 2');
});